INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_043_M4', 'Non-Isothermal Reactor Analysis', '4', 'Develops the analytical methods used to formulate, solve, and evaluate problems non-isothermal reactor analysis. The module addresses energy balances, heat generation, heat removal, ignition, and multiplicity, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M4', 'Active'), ('MOD_COURSE_043_M5', 'Residence Time and Reactor Performance', '5', 'Examines the concepts and methods required to understand and work with residence time and reactor performance. The module addresses RTD, E-curves, F-curves, segregation, and non-ideal flow, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M5', 'Active'), ('MOD_COURSE_043_M6', 'Heterogeneous Reactions', '6', 'Examines the concepts and methods required to understand and work with heterogeneous reactions. The module addresses gas-solid reactions, fluid-solid systems, catalyst pellets, and effectiveness factors, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M6', 'Active'), ('MOD_COURSE_043_M7', 'Reactor Design and Scale-Up', '7', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution reactor design and scale-up. The module addresses reactor selection, mixing, heat transfer, safety, and scale-up constraints, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M7', 'Active'), ('MOD_COURSE_044_M1', 'Process Measurement', '1', 'Develops the measurement and interpretation framework needed to obtain and use reliable evidence process measurement. The module addresses temperature, pressure, flow, level, analytical measurements, and sensor dynamics, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M1', 'Active'), ('MOD_COURSE_044_M2', 'Final Control Elements', '2', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour final control elements. The module addresses control valves, valve characteristics, actuators, positioners, and sizing principles, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M2', 'Active'), ('MOD_COURSE_044_M3', 'Process Dynamics', '3', 'Examines the concepts and methods required to understand and work with process dynamics. The module addresses first-order and higher-order models, dead time, process gain, and dynamic testing, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M3', 'Active'), ('MOD_COURSE_044_M4', 'Feedback Control', '4', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour feedback control. The module addresses closed-loop control, PID structure, stability, setpoint tracking, and disturbance rejection, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M4', 'Active'), ('MOD_COURSE_044_M5', 'Controller Tuning', '5', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour controller tuning. The module addresses Ziegler-Nichols, Cohen-Coon, IMC, robustness, and performance criteria, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M5', 'Active'), ('MOD_COURSE_044_M6', 'Advanced Process Control', '6', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour advanced process control. The module addresses cascade, feedforward, ratio control, override control, and model predictive control, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M6', 'Active'), ('MOD_COURSE_044_M7', 'Industrial Control Systems', '7', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour industrial control systems. The module addresses PLC, DCS, SCADA, alarm management, cybersecurity basics, and safety instrumented systems, with emphasis on their relationships, assumptions, analytical use, and application within Process Control and Instrumentation.', 'MSD_COURSE_044_M7', 'Active'), ('MOD_COURSE_045_M1', 'Magnetic Circuits and Electromechanical Conversion', '1', 'Examines the concepts and methods required to understand and work with magnetic circuits and electromechanical conversion. The module addresses magnetic circuits, induced EMF, torque production, and energy conversion, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M1', 'Active'), ('MOD_COURSE_045_M2', 'Transformers', '2', 'Examines the concepts and methods required to understand and work with transformers. The module addresses ideal transformer, equivalent circuit, losses, regulation, and tests, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M2', 'Active'), ('MOD_COURSE_045_M3', 'DC Machines', '3', 'Examines the concepts and methods required to understand and work with dc machines. The module addresses construction, EMF equation, torque, characteristics, and speed control, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M3', 'Active'), ('MOD_COURSE_045_M4', 'Induction Machines', '4', 'Examines the concepts and methods required to understand and work with induction machines. The module addresses rotating magnetic field, equivalent circuit, torque-slip, starting, and speed control, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M4', 'Active'), ('MOD_COURSE_045_M5', 'Synchronous Machines', '5', 'Examines the concepts and methods required to understand and work with synchronous machines. The module addresses EMF, phasors, synchronous impedance, power-angle relation, and excitation, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M5', 'Active'), ('MOD_COURSE_045_M6', 'Machine Performance and Testing', '6', 'Examines the concepts and methods required to understand and work with machine performance and testing. The module addresses loss segregation, efficiency, temperature rise, load tests, and condition assessment, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M6', 'Active'), ('MOD_COURSE_045_M7', 'Machine Applications and Drives', '7', 'Examines the concepts and methods required to understand and work with machine applications and drives. The module addresses motor selection, braking, variable-speed drives, duty cycles, and protection, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Machines.', 'MSD_COURSE_045_M7', 'Active'), ('MOD_COURSE_046_M1', 'Power-System Components and Models', '1', 'Examines the constituent materials or components, their properties, and their influence on system performance power-system components and models. The module addresses generators, transformers, lines, cables, loads, and per-unit system, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M1', 'Active'), ('MOD_COURSE_046_M2', 'Transmission and Distribution', '2', 'Examines the concepts and methods required to understand and work with transmission and distribution. The module addresses line parameters, voltage regulation, distribution feeders, and network topology, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M2', 'Active'), ('MOD_COURSE_046_M3', 'Power-Flow Analysis', '3', 'Develops the analytical methods used to formulate, solve, and evaluate problems power-flow analysis. The module addresses bus types, admittance matrix, Gauss-Seidel, Newton-Raphson, and fast decoupled methods, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M3', 'Active'), ('MOD_COURSE_046_M4', 'Fault Analysis', '4', 'Develops the analytical methods used to formulate, solve, and evaluate problems fault analysis. The module addresses symmetrical components, balanced faults, unbalanced faults, and short-circuit levels, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M4', 'Active'), ('MOD_COURSE_046_M5', 'Protection Systems', '5', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance protection systems. The module addresses relays, overcurrent protection, distance protection, differential protection, and coordination, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M5', 'Active'), ('MOD_COURSE_046_M6', 'Power-System Stability', '6', 'Examines the concepts and methods required to understand and work with power-system stability. The module addresses transient stability, small-signal stability, rotor angle, and voltage stability, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M6', 'Active'), ('MOD_COURSE_046_M7', 'System Operation and Emerging Grids', '7', 'Examines the operational principles and decisions required to run the relevant processes or systems reliably system operation and emerging grids. The module addresses economic dispatch, state estimation, SCADA/EMS, distributed generation, and microgrids, with emphasis on their relationships, assumptions, analytical use, and application within Power Systems.', 'MSD_COURSE_046_M7', 'Active'), ('MOD_COURSE_047_M1', 'Power Semiconductor Devices', '1', 'Examines the concepts and methods required to understand and work with power semiconductor devices. The module addresses diodes, thyristors, MOSFETs, IGBTs, and SiC and GaN devices, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M1', 'Active'), ('MOD_COURSE_047_M2', 'Controlled Rectifiers', '2', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour controlled rectifiers. The module addresses uncontrolled rectifiers, phase-controlled converters, commutation, and harmonics, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M2', 'Active'), ('MOD_COURSE_047_M3', 'DC-DC Converters', '3', 'Examines the concepts and methods required to understand and work with dc-dc converters. The module addresses buck, boost, buck-boost, isolated converters, and continuous/discontinuous conduction, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M3', 'Active'), ('MOD_COURSE_047_M4', 'Inverters', '4', 'Examines the concepts and methods required to understand and work with inverters. The module addresses voltage-source inverters, current-source inverters, single-phase, and three-phase, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M4', 'Active'), ('MOD_COURSE_047_M5', 'PWM and Switching Control', '5', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour pwm and switching control. The module addresses carrier-based PWM, space-vector PWM, switching losses, and gate drives, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M5', 'Active'), ('MOD_COURSE_047_M6', 'Power Quality and Thermal Management', '6', 'Examines the concepts and methods required to understand and work with power quality and thermal management. The module addresses harmonics, power factor, EMI, thermal design, and heat sinks, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M6', 'Active'), ('MOD_COURSE_047_M7', 'Applications of Power Electronics', '7', 'Examines the concepts and methods required to understand and work with applications of power electronics. The module addresses motor drives, renewable interfaces, UPS, HVDC, and EV charging, with emphasis on their relationships, assumptions, analytical use, and application within Power Electronics.', 'MSD_COURSE_047_M7', 'Active'), ('MOD_COURSE_048_M1', 'Measurement Fundamentals and Errors', '1', 'Establishes the foundational models, terminology, and governing principles measurement fundamentals and errors. The module addresses accuracy, precision, sensitivity, resolution, and systematic and random error, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M1', 'Active'), ('MOD_COURSE_048_M2', 'Electrical Measuring Instruments', '2', 'Develops the measurement and interpretation framework needed to obtain and use reliable evidence electrical measuring instruments. The module addresses PMMC, moving-iron, dynamometer, digital instruments, and instrument transformers, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M2', 'Active'), ('MOD_COURSE_048_M3', 'Sensors and Transducers', '3', 'Examines the concepts and methods required to understand and work with sensors and transducers. The module addresses resistive, inductive, capacitive, thermoelectric, magnetic, and optical transducers, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M3', 'Active'), ('MOD_COURSE_048_M4', 'Signal Conditioning and Data Acquisition', '4', 'Examines the concepts and methods required to understand and work with signal conditioning and data acquisition. The module addresses amplification, filtering, isolation, ADC/DAC, sampling, and multiplexing, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M4', 'Active'), ('MOD_COURSE_048_M5', 'Measurement Systems and Calibration', '5', 'Develops the measurement and interpretation framework needed to obtain and use reliable evidence measurement systems and calibration. The module addresses traceability, calibration procedures, reference standards, and adjustment versus calibration, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M5', 'Active'), ('MOD_COURSE_048_M6', 'Uncertainty and Statistical Evaluation', '6', 'Develops the analytical methods used to formulate, solve, and evaluate problems uncertainty and statistical evaluation. The module addresses uncertainty components, propagation, repeatability, reproducibility, and confidence intervals, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M6', 'Active'), ('MOD_COURSE_048_M7', 'Instrumentation Applications', '7', 'Develops the measurement and interpretation framework needed to obtain and use reliable evidence instrumentation applications. The module addresses power measurements, energy measurement, process instrumentation, data logging, and remote measurement, with emphasis on their relationships, assumptions, analytical use, and application within Electrical Measurements and Instrumentation.', 'MSD_COURSE_048_M7', 'Active'), ('MOD_COURSE_049_M1', 'Signal Representation', '1', 'Examines the concepts and methods required to understand and work with signal representation. The module addresses continuous/discrete signals, energy and power, transformations, and complex exponentials, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M1', 'Active'), ('MOD_COURSE_049_M2', 'Linear Time-Invariant Systems', '2', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance linear time-invariant systems. The module addresses linearity, time invariance, convolution, impulse response, and system properties, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M2', 'Active'), ('MOD_COURSE_049_M3', 'Fourier Analysis', '3', 'Develops the analytical methods used to formulate, solve, and evaluate problems fourier analysis. The module addresses Fourier series, Fourier transform, spectra, bandwidth, and filtering, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M3', 'Active'), ('MOD_COURSE_049_M4', 'Laplace Transform and System Analysis', '4', 'Develops the analytical methods used to formulate, solve, and evaluate problems laplace transform and system analysis. The module addresses Laplace transform, transfer functions, poles and zeros, and stability, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M4', 'Active'), ('MOD_COURSE_049_M5', 'Z Transform and Discrete-Time Systems', '5', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance z transform and discrete-time systems. The module addresses Z transform, ROC, difference equations, and digital-system response, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M5', 'Active'), ('MOD_COURSE_049_M6', 'Sampling and Reconstruction', '6', 'Examines the concepts and methods required to understand and work with sampling and reconstruction. The module addresses Nyquist rate, aliasing, reconstruction, and quantization, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M6', 'Active'), ('MOD_COURSE_049_M7', 'Applications and System Characterization', '7', 'Examines the concepts and methods required to understand and work with applications and system characterization. The module addresses frequency response, filters, modulation concepts, and signal measurement, with emphasis on their relationships, assumptions, analytical use, and application within Signals and Systems.', 'MSD_COURSE_049_M7', 'Active'), ('MOD_COURSE_050_M1', 'Foundations of Environmental Law', '1', 'Establishes the foundational models, terminology, and governing principles foundations of environmental law. The module addresses environmental rights, public trust, precaution, polluter pays, and sustainable development, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M1', 'Active'), ('MOD_COURSE_050_M2', 'Environmental Institutions and Regulatory Structure', '2', 'Examines the concepts and methods required to understand and work with environmental institutions and regulatory structure. The module addresses regulatory authorities, delegated legislation, jurisdiction, and environmental governance, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M2', 'Active'), ('MOD_COURSE_050_M3', 'Pollution Control Law', '3', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour pollution control law. The module addresses air pollution regulation, water pollution regulation, waste regulation, and consent mechanisms, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M3', 'Active'), ('MOD_COURSE_050_M4', 'Environmental Liability and Enforcement', '4', 'Examines the concepts and methods required to understand and work with environmental liability and enforcement. The module addresses strict liability, environmental compensation, penalties, remediation, and compliance, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M4', 'Active') ON CONFLICT DO NOTHING;